--region handler
function ActivityDirectDrawMallGiftPackNode:OnClickHandler()
    if isNull(self._productDojo) then
        return
    end

    -- 免费商品
    if checkInt(self._productDojo.isFree) == 1 then
        if self._productDojo.currentStock <= 0 then
            GameUtils.Toast(localize("商品已售罄"))
        else
            ---@type ActivityDirectDrawComponent
            self._directDrawComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityDirectDrawComponent)

            ActivityDirectDrawMgr:FreeProductBuyReq(self._directDrawComponent:GetActivityDojo().id, self._productDojo.productId, function()
                self._directDrawComponent:GetActivityDojo().redDotHint = -1
                Events.Broadcast(Constants.EventNames.ActivityRedPointChange, self._directDrawComponent:GetActivityDojo().id, -1)
                if self.buyCb then
                    self.buyCb()
                end
            end)
        end
        return
    end

    -- 不免费商品

    UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonBuyItemDialog, parameters = {
        goodsId        = self._productVo.id,
        consumeNum      = self._productDojo.price,
        maxBuyNum      = self._productDojo.currentStock,
        unlimited      = checkNumber(self._productDojo.stock) == -1,
        rewards        = self._productDojo.rewards,
        isShowNum = true,
        isPayMoney    = true,
        channelProductId = self._productDojo.channelProductId,
        isBackDialog = true,
        --isCloseSDKSecondConfirm = true,
        buyCb = function ()
            local payInfo = {
                productId = self._productDojo.productId,
                channelProductId = self._productDojo.channelProductId,
                payAmount = self._productDojo.price
            }
            SDKService:GetInstance():PayMoney({
                productId = self._productDojo.productId,
                channelProductId = self._productDojo.channelProductId,
                productDesc = self._productVo.desc,
                payAmount = self._productDojo.price,
                data = payInfo
            })
        end
    }}, {
        { id = Constants.UITypeIds.UIActivityDirectDrawPurchaseDialog }
    })
end
--endregion handler

--region public
---@param productNode ActivityDirectDrawMallProductDojo
function ActivityDirectDrawMallGiftPackNode:Refresh(productNode, onBuyCb)
    self.buyCb = onBuyCb
    self._productDojo = productNode
    ---@type GoodsVo
    self._productVo = GoodsConfMgr:GetInstance():GetGoodsVoById(productNode.showId)
    self:RefreshUI()
end
--endregion public

-- 页签类型
local TagType = {
    Discount  = 1, -- 折扣
    Recommend = 2, -- 推荐
    All       = 3, -- 折扣+推荐
}

--region private
function ActivityDirectDrawMallGiftPackNode:RefreshUI()

    CfUtils.SetActive(self.TimerGroup, false)

    -- 商品基本信息
    CfUtils.FillImage(self.ImgIcon, self._productVo.photoPath)

    -- 品质
    CfUtils.SetUISwitchImage(self.CatQuality, self._productVo.quality)

    -- 价格
    if self._productDojo.isFree == 1 then
        CfUtils.SetActive(self.FreeGroup, true)
        CfUtils.SetActive(self.PriceGroup, false)
        CfUtils.SetActive(self.redPoint, self._productDojo.currentStock > 0)
    else
        CfUtils.SetActive(self.FreeGroup, false)
        CfUtils.SetActive(self.PriceGroup, true)
        CfUtils.FillText(self.TxtOriginal, CfUtils.GetDisplayPrice(self._productDojo.price , self._productDojo.channelProductId))
        CfUtils.SetActive(self.redPoint, false)
    end

    CfUtils.SetUISwitchImage(self.GiftPackQuality, self._productDojo.isFree == 1 and 1 or 2)

    -- 商城库存
    local stock = self._productDojo.stock -- 总库存
    if stock == -1 then
        CfUtils.FillText(self.TxtNumber, '∞')
        CfUtils.SetActive(self.SellOutGroup, false)
    else
        CfUtils.FillText(self.TxtNumber, self._productDojo.currentStock)
        CfUtils.SetActive(self.SellOutGroup, self._productDojo.currentStock == 0)
    end

    -- 折扣角标
    local tabType = checkInt(self._productDojo.iconId)
    if tabType == TagType.Discount then
        CfUtils.FillText(self.DiscountTxtNumber, string.format('%s<size=18>%%</size>', checkInt(self._productDojo.iconTitle) * 100))
        CfUtils.SetActive(self.DiscountGroup, true)
        CfUtils.SetActive(self.ActivityGroup, false)
    elseif tabType == TagType.Recommend then
        CfUtils.SetActive(self.DiscountGroup, false)
        CfUtils.SetActive(self.ActivityGroup, true)
    elseif tabType == TagType.All then
        CfUtils.FillText(self.DiscountTxtNumber, string.format('%s<size=18>%%</size>', checkInt(self._productDojo.iconTitle) * 100))
        CfUtils.SetActive(self.DiscountGroup, true)
        CfUtils.SetActive(self.ActivityGroup, true)
    else
        CfUtils.SetActive(self.DiscountGroup, false)
        CfUtils.SetActive(self.ActivityGroup, false)
    end

    ---@type GiftGoodsVo
    local giftGoodsVo = CfUtils.GetCfVo(AutoIds.IdSetting111, "GiftGoodsVo", self._productDojo.showId)
    self.goodsListScr:FreshBaseUI(giftGoodsVo.showGoodsList)
end
--endregion private

